'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var discreteUniform = require( '@stdlib/random/discrete-uniform' );
var MultiSlice = require( '@stdlib/slice/multi' );
var Slice = require( '@stdlib/slice/ctor' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var toFilledSlice = require( './../lib' );


// VARIABLES //

var types = [ 'float64' ];
var orders = [ 'row-major', 'column-major' ];


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {NonNegativeIntegerArray} shape - ndarray shape
* @param {string} xtype - input ndarray data type
* @param {string} order - memory layout
* @returns {Function} benchmark function
*/
function createBenchmark( shape, xtype, order ) {
	var x;
	var s;

	x = discreteUniform( shape, -10, 10, {
		'dtype': xtype,
		'order': order
	});
	s = new MultiSlice( new Slice( 1, shape[ 0 ]-1 ), new Slice( 1, shape[ 1 ]-1 ) );
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var out;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			out = toFilledSlice( x, i, s );
			if ( typeof out !== 'object' ) {
				b.fail( 'should return an ndarray' );
			}
		}
		b.toc();
		if ( !isndarrayLike( out ) ) {
			b.fail( 'should return an ndarray' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var len;
	var min;
	var max;
	var ord;
	var sh;
	var t1;
	var f;
	var i;
	var j;
	var k;
	var n;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < orders.length; k++ ) {
		ord = orders[ k ];
		for ( j = 0; j < types.length; j++ ) {
			t1 = types[ j ];
			for ( i = min; i <= max; i++ ) {
				len = pow( 10, i );

				n = floor( sqrt( len ) );
				sh = [ n, n ];
				len = n * n;
				f = createBenchmark( sh, t1, ord );
				bench( format( '%s:ndims=%d,len=%d,shape=[%s],xorder=%s,xtype=%s', pkg, sh.length, len, sh.join( ',' ), ord, t1 ), f );
			}
		}
	}
}

main();
